<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="card"><h1>Monitoring Peserta</h1><p class="muted">Status aktif berdasarkan heartbeat terakhir. Peserta yang kehilangan jaringan mungkin tampak tidak aktif sampai terhubung kembali.</p><table><tr><th>Peserta</th><th>Ujian</th><th>Mulai</th><th>Terakhir aktif</th><th>Status koneksi</th></tr><?php foreach($attempts as $a): $fresh=!empty($a['last_seen_at'])&&strtotime($a['last_seen_at'])>time()-90; ?><tr><td><?= esc($a['full_name']) ?><br><?= esc($a['username']) ?></td><td><?= esc($a['title']) ?></td><td><?= esc($a['started_at']) ?></td><td><?= esc($a['last_seen_at']??'—') ?></td><td><?= $fresh?'Aktif baru-baru ini':'Tidak ada heartbeat terbaru' ?></td></tr><?php endforeach ?></table></div><?= $this->endSection() ?>